def _correct(flags, weights):
    total = sum(weights)
    if total == 0:
        return None
    return sum(w for f, w in zip(flags, weights) if f == 1) / total

def _unweighted(flags, weights):
    if sum(weights) == 0:
        return None
    return sum(flags) / len(flags)

def _zero_not_none(flags, weights):
    total = sum(weights)
    if total == 0:
        return 0.0
    return sum(w for f, w in zip(flags, weights) if f == 1) / total

def _run_with(impl):
    globals()["weighted_share"] = impl
    test_weighted_share()

